data.minimal_example:
import 'package:chewie/chewie.dart';
import 'package:video_player/video_player.dart';

final controller = VideoPlayerController.networkUrl(Uri.parse('https://example.com/video.mp4'));
await controller.initialize();
final chewieController = ChewieController(videoPlayerController: controller, autoPlay: true, looping: true);

Chewie(controller: chewieController);
